// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        address currentCeo = c.ceoAddress();
        vm.prank(currentCeo);
        c.DrugDealer();
        assertEq(c.ceoAddress(), currentCeo, "ceoAddress must stay msg.sender (= current CEO) after DrugDealer by CEO");
    }
}
